# Combining Counts
# Code to combine different count matricies generated by different alignment runs

# Import libraries 
library(tidyverse)

# Read counts into variables
# Iyer Lab Counts
rawcountsIyer <-  read.table("../Scaled_Inputs/ZL_salmon.merged.gene_counts_length_scaled.tsv", 
                          sep="\t", header=TRUE, check.names=FALSE)
# Primary Sensory
rawcountsPrimaryDRG <- read.table("../Scaled_Inputs/NguyenDRG_salmon.merged.gene_counts_length_scaled.tsv",
                                  sep="\t", header=TRUE, check.names=FALSE)
# Primary Sympathetic
rawcountsPrimarySG <- read.table("../Scaled_Inputs/HabermanSG_salmon.merged.gene_counts_length_scaled.tsv",
                                 sep="\t", header=TRUE, check.names=FALSE)
# Primary Schwann Cells
rawcountsPrimarySchwanns <- read.table("../Scaled_Inputs/MajdPrimary_salmon.merged.gene_counts_length_scaled.tsv",
                                       sep="\t", header=TRUE, check.names=FALSE)
# Other Neural Crest
rawcountsFattahiTNC <- read.table("../Scaled_Inputs/FattahiNCs_salmon.merged.gene_counts_length_scaled.tsv",
                                       sep="\t", header=TRUE, check.names=FALSE)
# Other Sympathetic
rawcountsWuSymp <- read.table("../Scaled_Inputs/WuSymNs_salmon.merged.gene_counts_length_scaled.tsv",
                                 sep="\t", header=TRUE, check.names=FALSE)
rawcountsLiuSGO <- read.table("../Scaled_Inputs/LiuSympO_salmon.merged.gene_counts_length_scaled.tsv",
                                 sep="\t", header=TRUE, check.names=FALSE)
# Other Sensory
rawcountsDeng28Sens <- read.table("../Scaled_Inputs/DengSNs_salmon.merged.gene_counts_length_scaled.tsv",
                                 sep="\t", header=TRUE, check.names=FALSE)
rawcountsDeng56Sens <- read.table("../Scaled_Inputs/DengD56SNs_salmon.merged.gene_counts_length_scaled.tsv",
                                 sep="\t", header=TRUE, check.names=FALSE)
rawcountsCantorSens <- read.table("../Scaled_Inputs/CantorSNs_salmon.merged.gene_counts_length_scaled.tsv",
                                 sep="\t", header=TRUE, check.names=FALSE)
rawcountsMalkaSens <- read.table("../Scaled_Inputs/Malka-gSNs_salmon.merged.gene_counts_length_scaled.tsv",
                                 sep="\t", header=TRUE, check.names=FALSE)
# Other Schwann Cells
rawcountsOtherSchwann <- read.table("../Scaled_Inputs/MajdPrimary_salmon.merged.gene_counts_length_scaled.tsv",
                                    sep="\t", header=TRUE, check.names=FALSE)
  
# Select out the relevant columns of the count maticies
countsIyer <- rawcountsIyer
countsPrimaryDRG <- rawcountsPrimaryDRG[, c("gene_id", "gene_name", "NguyenDRG_34FemA", "NguyenDRG_36Fem")]
countsPrimarySG <- rawcountsPrimarySG
countsPrimarySchwann <- rawcountsPrimarySchwanns[, c("gene_id", "gene_name", "PrimarySchwanns1", "PrimarySchwanns2")]
countsOtherTNC <- rawcountsFattahiTNC
countsOtherSymp <- merge(rawcountsWuSymp, rawcountsLiuSGO, by=c("gene_id", "gene_name"))
sens_tables <- list(rawcountsDeng28Sens, rawcountsDeng56Sens, rawcountsCantorSens, rawcountsMalkaSens)
countsOtherSens <- Reduce(function(x, y) merge(x, y, by=c("gene_id", "gene_name")), sens_tables)
countsOtherSchwann <- rawcountsOtherSchwann[, c("gene_id", "gene_name", "SC_old1", "SC_old2", "SC_young1", "SC_young2")]
  
# combine counts and write to new tsv for further analysis
count_list <- list(
  countsIyer,
  countsPrimaryDRG,
  countsPrimarySG,
  countsPrimarySchwann,
  countsOtherTNC,
  countsOtherSymp,
  countsOtherSens,
  countsOtherSchwann
)

# merge them all by gene_id and gene_name, keeping those columns only once
merged_counts <- Reduce(function(x, y) merge(x, y, by = c("gene_id", "gene_name"), all = TRUE), count_list)
write.table(merged_counts, "Combined_scaled_counts_v3.tsv", sep="\t", quote=FALSE, row.names=FALSE)

# Generate metadata mappings
sample_cols <- colnames(merged_counts)[-(1:2)]
metadata <- data.frame(
  sample = sample_cols,
  row.names = sample_cols,
  stringsAsFactors = FALSE
)

