                  "SC_old2"="Schwanns", "SC_young1"="Schwanns", "SC_young2"="Schwanns")
metadata$cell_type <- celltype_map[metadata$sample]

cellsource_map <- c("Lippmann_TNC_1003"="Iyer", "Lippmann_TNC_1107" = "Iyer",
