cellpub_map <- c("Lippmann_TNC_1003"="This Study", "Lippmann_TNC_1107" = "This Study",
                 "Fattahi_defaultNC_1"="Fattahi et al. (2016)", "Fattahi_defaultNC_2"="Fattahi et al. (2016)",
